#include <WiFi.h>
#include <WebServer.h>
#include <DHT.h>
#include "secrets.h"
#include "index.h"

#define DHT_PIN 4
#define DHT_TYPE DHT11   // если у тебя DHT22 — замени на DHT22

DHT dht(DHT_PIN, DHT_TYPE);
WebServer server(80);

void handleRoot() {
  server.send(200, "text/html", INDEX_HTML);
}

void handleData() {
  float t = dht.readTemperature();
  float h = dht.readHumidity();

  String json = "{";
  if (isnan(t) || isnan(h)) {
    json += "\"error\": true";
  } else {
    json += "\"error\": false,";
    json += "\"temp\": " + String(t, 1) + ",";
    json += "\"hum\": " + String(h, 1);
  }
  json += "}";
  server.send(200, "application/json", json);
}

void setup() {
  Serial.begin(115200);
  dht.begin();

  WiFi.begin(SECRET_SSID, SECRET_PASS);
  Serial.print("Connecting");
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("Open http://");
  Serial.println(WiFi.localIP());

  server.on("/", handleRoot);
  server.on("/data", handleData);
  server.begin();
}

void loop() {
  server.handleClient();
}

