const char INDEX_HTML[] PROGMEM = R"rawliteral(
<!DOCTYPE html>
<html lang="ru">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Погода дома</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    min-height: 100vh;
    display: flex;
    justify-content: center;
    align-items: center;
    background: linear-gradient(135deg, #0f0c29, #302b63, #24243e);
    background-size: 400% 400%;
    animation: shift 15s ease infinite;
    font-family: 'Segoe UI', Arial, sans-serif;
  }

  @keyframes shift {
    0% { background-position: 0% 50%; }
    50% { background-position: 100% 50%; }
    100% { background-position: 0% 50%; }
  }

  .card {
    text-align: center;
    padding: 40px 60px;
    border-radius: 24px;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.12);
    backdrop-filter: blur(20px);
    box-shadow: 0 25px 60px rgba(0, 0, 0, 0.45);
    color: #fff;
  }

  h1 {
    font-size: 22px;
    font-weight: 400;
    color: rgba(255, 255, 255, 0.7);
    margin-bottom: 24px;
  }

  .value {
    font-size: clamp(48px, 10vw, 96px);
    font-weight: 700;
    color: #fff;
    text-shadow: 0 0 30px rgba(120, 140, 255, 0.55);
  }

  .unit {
    font-size: 0.4em;
    color: #8ec5ff;
    margin-left: 4px;
  }

  .label {
    font-size: 16px;
    color: rgba(255, 255, 255, 0.6);
    margin-top: 4px;
  }

  .divider {
    margin: 28px auto;
    width: 60%;
    border-top: 1px solid rgba(255, 255, 255, 0.15);
  }

  .status {
    margin-top: 20px;
    font-size: 13px;
    color: rgba(255, 255, 255, 0.45);
  }
</style>
</head>
<body>

<div class="card">
  <h1>Климат ESP32</h1>

  <div class="value" id="temp">--<span class="unit">°C</span></div>
  <div class="label">Температура</div>

  <div class="divider"></div>

  <div class="value" id="hum">--<span class="unit">%</span></div>
  <div class="label">Влажность</div>

  <div class="status" id="status">Обновляю...</div>
</div>

<script>
  async function poll() {
    try {
      const r = await fetch('/data');
      const d = await r.json();

      if (d.error) {
        document.getElementById('status').textContent = 'Датчик не отвечает';
      } else {
        document.getElementById('temp').innerHTML = d.temp + '<span class="unit">°C</span>';
        document.getElementById('hum').innerHTML = d.hum + '<span class="unit">%</span>';
        const now = new Date().toLocaleTimeString('ru-RU');
        document.getElementById('status').textContent = 'Обновлено в ' + now;
      }
    } catch (e) {
      document.getElementById('status').textContent = 'Нет связи';
    }
  }

  poll();
  setInterval(poll, 1000);
</script>

</body>
</html>
)rawliteral";
